/* @autogenerated */
package net.civeira.phylax.features.oauth.delegatelogin.domain;

import lombok.Builder;
import lombok.Data;

/**
 * Details required to build delegated provider requests and check their responses.
 *
 * Responsibilities: - Identify the delegated provider in use. - Carry the callback URL and the
 * values that tie the provider response to this login.
 *
 * Design notes: - Immutable value object created by builder. - The same details are used to build
 * the request and to validate the response.
 */
@Data
@Builder
public class DelegatedRequestDetails {
  /**
   * Provider identifier.
   */
  private String provider;
  /**
   * Callback URL registered at the provider (OAuth redirect URI, SAML ACS URL).
   */
  private String externalUrl;
  /**
   * The {@code state} (OAuth) or {@code RelayState} (SAML) sent to the provider.
   */
  private String state;
  /**
   * PKCE verifier for OAuth providers.
   */
  private String codeVerifier;
  /**
   * ID of the SAML AuthnRequest.
   */
  private String requestId;

  /**
   * Builds the details of a pending login.
   *
   * @param pending pending delegation
   * @param state its state
   * @return details
   */
  public static DelegatedRequestDetails of(PendingDelegation pending, String state) {
    return DelegatedRequestDetails.builder().provider(pending.getProvider())
        .externalUrl(pending.getCallbackUrl()).state(state).codeVerifier(pending.getCodeVerifier())
        .requestId(pending.getRequestId()).build();
  }
}
